function initTheme(){const e=localStorage.getItem("theme")||"light";document.documentElement.setAttribute("data-theme",e)}window.addEventListener("storage",e=>{e.key==="theme"&&document.documentElement.setAttribute("data-theme",e.newValue)}),setInterval(()=>{const e=localStorage.getItem("theme"),t=document.documentElement.getAttribute("data-theme");e&&e!==t&&document.documentElement.setAttribute("data-theme",e)},500),initTheme(),console.log("\u{1F3A8} Privacy page theme sync enabled");
